function dcIc(t,x,y,sc){return '<g transform="translate('+x+','+y+')'+(sc?' scale('+sc+')':'')+'">'+nkIcon(t)+'</g>'}
GI["Data center"]=function(){return giSt({w:420,h:150,nodes:[{id:'b',t:'building',x:110,y:70,l:'Data center'}],extra:giLbl(300,40,'électricité')+giLbl(300,74,'froid')+giLbl(300,108,'réseau'),links:[]},'Un bâtiment fait pour une chose : faire tourner des serveurs sans jamais s\'arrêter, avec électricité, froid et réseau en continu.')};
GI["Tier"]=function(){return giWrap(giSvg(420,150,[['I','99,671 %',30],['II','99,741 %',55],['III','99,982 %',85],['IV','99,995 %',110]].map(function(t,i){var x=40+i*95;return '<rect x="'+x+'" y="'+(130-t[2])+'" width="60" height="'+t[2]+'" rx="6" fill="var(--vd)" opacity="'+(.4+i*.2)+'"/>'+giT(x+30,124-t[2],'Tier '+t[0],{b:1,s:13})+giT(x+30,146,t[1],{s:11.5,m:1,c:'var(--muted)'})}).join('')),'Le niveau de fiabilité du bâtiment. Tier III : on peut tout entretenir sans couper. Tier IV : une panne de n\'importe quoi ne coupe rien.')};
GI["PUE"]=function(){return giWrap(giSvg(420,110,'<rect x="20" y="30" width="250" height="40" rx="8" fill="var(--vd)"/>'+giT(145,55,'1 kW pour les serveurs',{c:'#fff',b:1,s:13})+'<rect x="274" y="30" width="125" height="40" rx="8" fill="#E8840C"/>'+giT(336,55,'0,5 kW froid…',{c:'#fff',b:1,s:12})+giT(210,98,'PUE = 1,5 kW ÷ 1 kW = 1,5',{m:1,s:13})),'L\'énergie totale du bâtiment divisée par celle des serveurs. Plus c\'est proche de 1, moins on gaspille.')};
GI["Baie"]=function(){return giWrap(giSvg(360,170,dcIc('rack',100,85,1.15)+giT(190,50,'≈ 60 cm de large',{a:'start',s:13})+giT(190,80,'≈ 2 m de haut',{a:'start',s:13})+giT(190,110,'42 emplacements (U)',{a:'start',s:13,b:1})),'L\'armoire standard où l\'on fixe serveurs, switchs et stockage.')};
GI["U (unité)"]=function(){var s='';for(var i=0;i<6;i++)s+='<rect x="120" y="'+(14+i*24)+'" width="160" height="21" rx="2" fill="'+(i===2?'var(--vd)':'#2B303B')+'"/>'+giT(108,29+i*24,String(42-i),{a:'end',m:1,s:11,c:'var(--muted)'});s+='<path d="M296 62v21M290 62h12M290 83h12" stroke="var(--ink)" stroke-width="1.5"/>'+giT(308,77,'1U = 44,45 mm',{a:'start',s:13,b:1});return giWrap(giSvg(440,170,s),'L\'unité de hauteur dans une baie. Un serveur fait 1U ou 2U.')};
GI["PDU"]=function(){var s='<rect x="190" y="10" width="34" height="150" rx="8" fill="#E8840C"/>';for(var i=0;i<6;i++)s+='<rect x="198" y="'+(22+i*22)+'" width="18" height="14" rx="3" fill="#5A2E05"/>';s+='<path d="M216 51C260 51 270 70 300 70" stroke="#2B303B" stroke-width="3" fill="none"/>'+dcIc('server',340,70,.6)+giT(160,90,'PDU A',{a:'end',b:1,s:14,c:'#E8840C'});return giWrap(giSvg(420,170,s),'Le bandeau de prises de la baie. Il y en a deux, A et B, sur deux alimentations différentes.')};
GI["Onduleur"]=function(){return giWrap(giSvg(400,150,dcIc('ups',90,74,1.2)+'<rect x="200" y="44" width="150" height="50" rx="8" fill="none" stroke="#1F9D6B" stroke-width="3"/><rect x="350" y="60" width="8" height="18" rx="2" fill="#1F9D6B"/><rect x="208" y="52" width="100" height="34" rx="4" fill="#1F9D6B"/>'+giT(275,118,'quelques minutes de réserve',{s:12.5,c:'var(--muted)'})),'Il lisse le courant et garde de l\'énergie en batteries, le temps que le groupe électrogène démarre.')};
GI["Groupe électrogène"]=function(){return giWrap(giSvg(400,130,dcIc('gen',140,64,1.3)+giT(260,56,'démarre en ≈ 10 s',{a:'start',s:13})+giT(260,80,'tient tant qu\'il a',{a:'start',s:13})+giT(260,98,'du carburant',{a:'start',s:13})),'Un moteur qui produit l\'électricité quand le réseau est coupé.')};
GI["ATS"]=function(){return giSt({w:420,h:150,nodes:[{id:'n',t:'pylon',x:60,y:50,l:'Réseau'},{id:'g',t:'gen',x:70,y:118},{id:'a',t:'ats',x:230,y:80,l:'Inverseur'},{id:'u',t:'ups',x:360,y:80}],links:[['n','a'],['g','a','ko'],['a','u']]},'L\'aiguillage automatique : il prend le courant du réseau, ou du groupe quand le réseau tombe.')};
GI["N+1"]=function(){var s='';for(var i=0;i<4;i++)s+=dcIc('crah',70+i*90,60,.9)+(i===3?giLbl(70+i*90,124,'en secours'):giLbl(70+i*90,124,'utile'));return giWrap(giSvg(420,140,s),'Un équipement de plus que le besoin : 4 climatiseurs pour un besoin de 3. Une panne est absorbée.')};
GI["2N"]=function(){return giSt({w:430,h:160,nodes:[{id:'a1',t:'pylon',x:50,y:40},{id:'a2',t:'ups',x:170,y:40},{id:'b1',t:'pylon',x:50,y:124},{id:'b2',t:'ups',x:170,y:124},{id:'s',t:'server',x:340,y:82}],links:[['a1','a2'],['a2','s'],['b1','b2'],['b2','s']],extra:giLbl(260,40,'chaîne A')+giLbl(260,124,'chaîne B','ko')},'Tout est doublé en deux chaînes complètes et indépendantes. On peut en perdre une entière.')};
GI["Allée froide"]=function(){var s='<rect x="20" y="58" width="380" height="44" rx="6" fill="#DCE6FB"/>';for(var i=0;i<6;i++)s+='<rect x="'+(40+i*60)+'" y="66" width="28" height="28" rx="3" fill="#9DB8F2"/><rect x="'+(34+i*60)+'" y="16" width="40" height="34" rx="3" fill="#2B303B"/><rect x="'+(34+i*60)+'" y="110" width="40" height="34" rx="3" fill="#2B303B"/>';return giWrap(giSvg(420,160,s+giT(210,84,'air froid · 22 °C',{b:1,s:13,c:'#1E4FB8'})),'L\'allée entre deux rangées de baies, face avant contre face avant : l\'air froid y monte du sol par des dalles percées.')};
